def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def hull(points):
        # Points are (column, row).
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts

        def cross(o, a, b):
            return ((a[0] - o[0]) * (b[1] - o[1])
                    - (a[1] - o[1]) * (b[0] - o[0]))

        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        return lower[:-1] + upper[:-1]

    def segment(a, b):
        x, y = a
        x2, y2 = b
        dx, dy = abs(x2 - x), abs(y2 - y)
        sx = 1 if x < x2 else -1
        sy = 1 if y < y2 else -1
        err = dx - dy
        points = []
        while True:
            points.append((y, x))
            if (x, y) == (x2, y2):
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x += sx
            if e2 < dx:
                err += dx
                y += sy
        return points

    for color in range(1, 10):
        points = [(c, r) for r in range(h) for c in range(w)
                  if grid[r][c] == color]
        if len(points) < 2:
            continue
        boundary = hull(points)
        if len(boundary) == 2:
            edges = [(boundary[0], boundary[1])]
        else:
            edges = list(zip(boundary, boundary[1:] + boundary[:1]))

        for a, b in edges:
            for r, c in segment(a, b):
                if out[r][c] == 0:
                    out[r][c] = color

    return out
